mapper.select:

g.del_flag='0'
  and g.activity_id=#{activityId}
  and g.guest_name like concat('%',#{guestName},'%')
  and g.phone like concat('%',#{phone},'%')
  and g.guest_type=#{guestType}
  and g.need_hotel=#{needHotel}
  and g.attend_flag=#{attendFlag}

order by g.sort_order asc, g.guest_id asc

mapper.update:
update yc_guest
guest_name=#{guestName}, phone=#{phone}, org_name=#{orgName}, title=#{title}, english_name=#{englishName}, guest_type=#{guestType}, avatar=#{avatar}, intro=#{intro}, need_hotel=#{needHotel}, check_in_date=#{checkInDate}, check_out_date=#{checkOutDate}, id_card=#{idCard}, attend_flag=#{attendFlag}, sort_order=#{sortOrder}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where guest_id=#{guestId}
